import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.dirname(fileURLToPath(import.meta.url));
const sourcePath = path.join(root, "src", "bookmarklet.js");
const source = await readFile(sourcePath, "utf8");

if (!source.trimStart().startsWith("(() =>")) {
  throw new Error("src/bookmarklet.js must remain a self-invoking function.");
}

const bookmarkletUrl = `javascript:${encodeURIComponent(source)}`;
const installerData = [
  "// Generated by build.mjs. Do not edit by hand.",
  `window.FAVICON_FX_BOOKMARKLET_URL = ${JSON.stringify(bookmarkletUrl)};`,
  "",
].join("\n");

await writeFile(path.join(root, "installer-data.js"), installerData, "utf8");
await writeFile(path.join(root, "bookmarklet.txt"), `${bookmarkletUrl}\n`, "utf8");

console.log(`Built bookmarklet from ${source.length.toLocaleString("en-US")} readable source characters.`);
console.log(`Encoded bookmark URL: ${bookmarkletUrl.length.toLocaleString("en-US")} characters.`);
